						<view class="skeleton-line short" style="width: 140rpx;"></view>
					</view>
					<view class="skeleton-dept-tag"></view>
				</view>
				<view class="skeleton-search-bar"></view>
			</view>

			<!-- 轮播骨架 -->
			<view class="skeleton-swiper-box"></view>

