				<view class="skeleton-notice-bar"></view>
				<view class="skeleton-notice-card"></view>
			</view>

			<!-- 快捷入口骨架 -->
			<view class="skeleton-quick-access">
				<view class="skeleton-section-title"></view>
				<view class="skeleton-quick-grid">
					<view class="skeleton-quick-item" v-for="i in 4" :key="i">
						<view class="skeleton-quick-icon"></view>
						<view class="skeleton-line short" style="width: 60rpx; margin-top: 12rpx;"></view>
					</view>
				</view>
			</view>
		</view>

		<!-- ========== 底部导航 ========== -->
		<u-tabbar :list="tabbar" :before-switch="beforeTabSwitch" icon-size="48" font-size="20" border-top hide-tab-bar
			active-color="#2979ff" inactive-color="#999"></u-tabbar>
	</view>
</template>

<script>
	export default {
		data() {
			return {
				pageLoading: true,
				popupStyle: {
					mode: "bottom",
					border_radius: 16,
					height: "90%"
				},
				userInfo: {},
				searchKeyword: '',
				swiperList: [],
				defaultSwiper: [{
					image: '/static/default_banner.png',
					title: '欢迎使用'
				}],
				menuList: [],
				menuSort: [666],
				showDetailPopup: false,
				noticeList: [],
				currentNotice: {
					title: '',
					content: '',
					publish_date: ''
				},
				// 颜色池（用于占位图标）
				colorPool: ['#2979ff', '#19be6b', '#ff9900', '#e74c3c', '#9b59b6', '#1abc9c', '#e67e22', '#3498db'],
				quickList: [{
						icon: 'scan',
						text: '扫一扫',
						bgColor: '#2979ff',
						action: 'scan'
					},
					{
						icon: 'calendar',
						text: '今日考勤',
						bgColor: '#19be6b',
						action: 'attendance'
					},
					{
						icon: 'chat',
						text: '消息',
						bgColor: '#ff9900',
						action: 'message'
					},
					{
						icon: 'setting',
						text: '设置',
						bgColor: '#909399',
						action: 'setting'
					}
				],
				tabbar: [{
						iconPath: "/static/icon_home.png",
						selectedIconPath: "/static/icon_home_sel.png",
						pagePath: "/pages/index/index",
						text: "首页"
					},
					{
						iconPath: "/static/icon_msg.png",
						selectedIconPath: "/static/icon_msg_sel.png",
						pagePath: "/pages/notice/index",
						text: "消息"
					},
					{
						iconPath: "/static/icon_mailList.png",
						selectedIconPath: "/static/icon_mailList_sel.png",
						pagePath: "/pages/contacts/index",
						text: "通讯录"
					},
					{
						iconPath: "/static/icon_user.png",
						selectedIconPath: "/static/icon_user_sel.png",
						pagePath: "/pages/user/index",
						text: "我的"
					}
				]
			};
		},
		computed: {
			departMentName() {
				// let employeeInfo = vk.getVuex('$user.employeeInfo.card') || {};
				return vk.getVuex('$user.employeeInfo.department_name') || '人事部';
			},
			hasLogin() {
				return !!vk.getVuex('$user.userInfo.username');
			},
			// 只显示前8个功能
			displayMenuList() {
				return this.menuList.slice(0, 8);
			}
		},
		async onLoad() {
			this.pageLoading = true;
			this.loadUserInfo();
			await Promise.all([
				this.loadSwiperList(),
				this.loadMenuList(),
				this.loadNoticeList()
			]);
			this.currentNotice = this.noticeList[0] || {
				title: '暂无通知',
				content: '暂无内容',
				publish_date: ''
			};
			this.pageLoading = false;
		},
		onShow() {
			this.refreshData();
			this.loadUnreadCount();
		},
		onPullDownRefresh() {
			this.refreshData();
			setTimeout(() => {
				uni.stopPullDownRefresh();
			}, 1000);
		},
		methods: {
			// -------- 数据加载 --------
			async loadSwiperList() {
				try {
					const res = await this.vk.callFunction({
						url: 'admin/opendb-banner/pub/getList',
						data: {
							pageSize: -1,
							pageIndex: 1
						}
					});
					if (res.code === 0 && res.rows.length) {
						this.swiperList = res.rows.map(e => ({
							image: e.bannerfile,
							title: e.title || ''
						}));
					}
				} catch (error) {
					console.error('加载轮播图失败:', error);
				}
			},
			async loadMenuList() {
				try {
					const url = this.hasLogin ? 'admin/common-functions/sys/getList' :
						'admin/common-functions/pub/getList';
					const res = await this.vk.callFunction({
						url: url,
						data: {
							status: 'enabled',
							sort: this.menuSort,
							pageSize: -1,
							pageIndex: 1
						}
					});
					if (res.code === 0) {
						this.menuList = res.rows.map(item => ({
							...item,
							_imgLoaded: true // 标记图片加载状态
						}));
					}
				} catch (error) {
					console.error('加载常用功能失败:', error);
				}
			},
			async loadNoticeList() {
				try {
					if (!this.hasLogin) return;
					const res = await this.vk.callFunction({
						url: 'admin/opendb-notice/pub/getListTop',
						data: {
							pageSize: -1,
							pageIndex: 1
						}
					});
					if (res.code === 0) {
						this.noticeList = res.rows;
					}
				} catch (error) {
					console.error('加载通知失败:', error);
				}
			},
			async loadUnreadCount() {
				try {
					if (!this.hasLogin) return;
					const res = await this.vk.callFunction({
						url: 'admin/bpmn/notification/pub/getUnreadCount',
						data: {
							userInfo: this.userInfo,
							pageSize: -1,
							pageIndex: 1
						}
					});
					if (res.code === 0) {
						this.tabbar[1].count = res.data.count || 0;
					}
				} catch (error) {
					console.error('加载未读数量失败:', error);
				}
			},
			loadUserInfo() {
				try {
					this.userInfo = vk.getVuex('$user.userInfo') || {};
				} catch (error) {
					console.error('加载用户信息失败:', error);
				}
			},
			refreshData() {
				console.log('刷新数据');
			},

			// -------- 图标颜色 --------
			getColor(index) {
				return this.colorPool[index % this.colorPool.length];
			},

			// -------- 图片加载失败处理 --------
			onIconError(event, item) {
				item._imgLoaded = false;
				this.$forceUpdate();
			},

			// -------- 交互事件 --------
			getGreeting() {
				const hour = new Date().getHours();
				if (hour < 9) return '早上好 ☀️';
				if (hour < 12) return '上午好 🌤';
				if (hour < 14) return '中午好 🌞';
				if (hour < 18) return '下午好 🌥';
				return '晚上好 🌙';
			},
			onSearch() {
				uni.navigateTo({
					url: '/pages/opendb-notice/index'
				});
			},
			onSwiperClick(index) {
				const item = this.swiperList[index];
				if (item?.url) {
					uni.navigateTo({
						url: item.url
					});
				}
			},
			goToPage(item) {
				if (!item.route) {
					uni.showToast({
						title: '功能开发中',
						icon: 'none'
					});
					return;
				}
				if (item.badge > 0) item.badge = 0;
				uni.navigateTo({
					url: item.route
				});
			},
			viewAllFunctions() {
				uni.navigateTo({
					url: '/pages/functions/index'
				});
			},
			viewAllNotices() {
				uni.navigateTo({
					url: '/pages/opendb-notice/index'
				});
			},
			onNoticeClick(index) {
				if (this.noticeList[index]) {
					this.currentNotice = this.noticeList[index];
				}
			},
			showDetail(item) {
				if (!item.title) return;
				this.currentNotice = {
					...item
				};
				this.showDetailPopup = true;
			},
			handleQuickAction(item) {
				switch (item.action) {
					case 'scan':
						uni.scanCode({
							success: (res) => {
								vk.alert(res, '提示', '确定');
							}
						});
						break;
					case 'attendance':
						// uni.navigateTo({
						// 	url: '/pages/clockin/index'
						// });
						break;
					case 'message':
						uni.switchTab({
							url: '/pages/notice/index'
						});
						break;
					case 'setting':
						uni.navigateTo({
							url: '/pages/setting/index'
						});
						break;
				}
			},
			beforeTabSwitch(index) {
				return true;
			}
		}
	};
</script>

